#include<bits/stdc++.h>
using namespace std;using U=uint64_t;using Z=int64_t;using Ed=pair<int,int>;const Z S=100000;void chk(bool b){if(!b)throw runtime_error("bad certificate");}
int main(int argc,char**av){chk(argc==3);ifstream fi(av[1]);set<U> todo;U code;while(fi>>code){int d=0;for(int j=0;j<21;j++)d+=bool((code>>(2*j))&3);if(d>=6&&d<=14)chk(todo.insert(code).second);}chk(todo.size()==2101);for(U z:{45141371560ull,45141371520ull,45141371392ull,10747945640ull,42991782400ull})chk(todo.erase(z));ifstream fc(av[2]);vector<Ed>E;for(int a=0;a<7;a++)for(int b=a+1;b<7;b++)E.emplace_back(a,b);int ct=0;Z lo=1ull<<50;while(fc>>code){chk(todo.erase(code));vector<Ed>D;vector<int> cell,id(21,-1);for(int b=1;b<7;b++)for(int a=0;a<b;a++){int s=code>>(b*(b-1)+2*a)&3;if(!s)continue;chk(s<3);int h=find(E.begin(),E.end(),Ed{a,b})-E.begin();cell.push_back(h);id[h]=D.size();D.emplace_back(s==1?a:b,s==1?b:a);}int d=D.size();vector<vector<Ed>>tr(14);int C[21][15]={};vector<int> ch;for(int e=0;e<d;e++){auto [a,b]=D[e];b+=7;vector<int>par(14,-1),ed(14);vector<int>q{a};par[a]=a;for(int s=0;s<(int)q.size();s++)for(auto [v,z]:tr[q[s]])if(par[v]<0)par[v]=q[s],ed[v]=z,q.push_back(v);if(par[b]<0){tr[a].emplace_back(b,e);tr[b].emplace_back(a,e);continue;}int k=ch.size();ch.push_back(cell[e]);C[e][k]=1;int sg=-1;for(int v=b;v!=a;v=par[v])C[ed[v]][k]=sg,sg=-sg;}
 int k=ch.size();chk(k<=10&&k>=1);vector<int>non;for(int h=0;h<21;h++)if(find(ch.begin(),ch.end(),h)==ch.end())non.push_back(h);int n0=non.size();vector<Z>mu(k*n0+k*k),alpha(105);for(auto* ar:{&mu,&alpha}){int m;chk(bool(fc>>m)&&m>=0&&m<=ar->size());int last=-1;while(m--){int i;Z x;chk(bool(fc>>i>>x)&&last<i&&i<ar->size()&&abs(x)<=102400000);if(ar==&alpha)chk(x>=0&&x<=S);(*ar)[i]=x;last=i;}}
 int mask[21];for(int h=0;h<21;h++)mask[h]=(1<<E[h].first)|(1<<E[h].second);vector<Ed> dis;for(int f=0;f<21;f++)for(int h=0;h<f;h++)if(!(mask[h]&mask[f]))dis.emplace_back(h,f);chk(dis.size()==105);
 Z lower[21];fill(lower,lower+21,INT64_MAX);int cap=1;for(int i=0;i<k;i++)cap*=3;for(int n=0;n<cap;n++){int z=n,t[15],w[21];for(int i=k-1;i>=0;i--)t[i]=z%3-1,z/=3;bool ok=true;for(int i=0;i<d;i++){int x=0;for(int j=0;j<k;j++)x+=C[i][j]*t[j];if(abs(x)>1){ok=false;break;}w[i]=x;}if(!ok)continue;
 for(int h=0;h<21;h++){int e=id[h];bool ok=true;for(int g=0;g<d;g++){if(!(mask[h]&mask[cell[g]]))continue;if(g==e)ok&=w[g]==-1;else if(e>=0&&(D[e].first==D[g].first||D[e].second==D[g].second))ok&=w[g]>=0;else ok&=w[g]==0;}if(!ok)continue;Z tmp=0;int cc=find(ch.begin(),ch.end(),h)-ch.begin();for(int a=0;a<k;a++)if(t[a])for(int j=0;j<n0;j++){int g=non[j],v=id[g],coeff=(h==g)-(cc<k&&v>=0?C[v][cc]:0);tmp-=mu[a*n0+j]*coeff*t[a];}
 for(int a=0;a<k;a++)for(int b=0;b<k;b++)tmp-=mu[k*n0+a*k+b]*(t[a]+7*(ch[a]==h))*t[b];
 int deg[21],pr[21];for(int f=0;f<21;f++){int g=id[f];deg[f]=2*(h==f)+(!(mask[h]&mask[f]))+(g>=0?w[g]:0);pr[f]=(h==f)?(g<0?2:1):(g>=0&&e>=0&&D[e].second==D[g].second?w[g]:0);}
 for(int p=0;p<105;p++)if(alpha[p]){auto [i,j]=dis[p];tmp-=alpha[p]*(((h==i)+pr[i])*deg[j]+pr[j]*deg[i]);}lower[h]=min(lower[h],tmp);}}
 Z v=16*accumulate(alpha.begin(),alpha.end(),Z(0));for(Z a:lower){chk(a!=INT64_MAX);v+=4*a;}chk(v>0);lo=min(lo,v);ct++;}
 chk(fc.eof()&&todo.empty());cout<<"Verified "<<ct<<" orientation bounds, upper denominator "<<S<<"; least positive numerator "<<lo<<".\n";}
